def mods(v):
    c=glob.glob(f'{v}/quantized/model.safetensors.index.json')+glob.glob(f'{v}/quantized/*/model.safetensors.index.json')
    p=os.path.dirname(c[0]); s=set()
    for f in glob.glob(p+'/model*.safetensors'):
