def _make_harness(name: str, cfg: EvalConfig, num_gpus: int):
    if name == "lm_eval":
        opts = cfg.lm_eval
        return HARNESSES.create(
            name,
            num_gpus=num_gpus,
            batch_size=cfg.batch_size,
            limit=cfg.limit,
